"use client";

import { motion } from "motion/react";

export function PulseLoaderTailwind({ size = 64, duration = 1.8 }) {
  return (
    <div role="status" aria-label="Loading" className="relative" style={{ width: size, height: size }}>
      {[0, 1, 2].map((i) => (
        <motion.span
          key={i}
          aria-hidden
          className="absolute inset-0 rounded-full border-2 border-sky-400"
          initial={{ scale: 0, opacity: 1 }}
          animate={{ scale: 1, opacity: 0 }}
          transition={{ duration, repeat: Infinity, delay: (i * duration) / 3, ease: "easeOut" }}
        />
      ))}
      <span aria-hidden className="absolute inset-[40%] rounded-full bg-sky-400" />
    </div>
  );
}
